// The Touch test: where the pointer is, the gesture the frame made of it, and
// the path of a drag. Held down and moved, a finger, a pen or a mouse leaves a
// trail from where it went down (the ring) to where it is (the dot, red while
// held, blue once lifted), with a small dot for every move the scene heard.
// The trail stays until the next press, so a whole gesture can be read after.
//
// The app hears the pointer itself (config.json "events", onEvent). A move
// only adds a point and asks for a render: moves that arrive while a render
// runs reach the scene as the newest one alone (the contract's coalesce), so
// a slow panel gets fewer points, joined by straight lines, and never a
// backlog. On e-paper every move would be a refresh, so there the gesture is
// drawn once, when the finger lifts.
//
// Positions are in panel pixels, while a big panel runs this app at a render
// scale (app.frame.scale, e.g. 2 at 1600x1200): the canvas it is told about is
// the panel divided by the scale and the drawing is stretched back. So the
// positions and the sizes that should stay as they are (the hairlines, the
// trail, the text) are worked out in panel pixels and divided by it.

// The most points a trail keeps. Past it every other one goes, the press and
// the newest stay: a long drag keeps its whole shape in a bounded piece of an
// ESP32's JS heap.
const MAX_POINTS = 256
// A move this close to the trail's last point (panel pixels) moves the dot
// and adds no point.
const MIN_STEP = 2
// The trail is drawn in pieces of this many points, each a path of its own.
// An LCD repaints only what changed since the last frame, so a drag redraws
// its newest piece and not the whole trail.
const PIECE = 32

type Seen = {
  last: string // what the scene heard last, in words
  x: number // where, in panel pixels
  y: number
  down: boolean // the trail's pointer is held
  id: number // the pointer the trail follows
  count: number // events heard, moves left out
  moves: number // moves since the press
  trail: number[] // x0, y0, x1, y1, ... since the press
  paper: boolean // e-paper, as the last render found it
}

// Kept with frameos.remember at every render and every event but a move: an
// ESP32 short of memory drops the interpreter, and this module, after a render.
let seen: Seen | null = null

function load(): Seen {
  if (!seen) {
    const kept: any = frameos.recall('seen')
    seen = kept && Array.isArray(kept.trail) ? kept : {
      last: 'Touch, click or drag the picture', x: 0, y: 0, down: false, id: -1, count: 0, moves: 0, trail: [],
      paper: false,
    }
  }
  return seen
}

const keep = () => frameos.remember('seen', seen)

function add(s: Seen, x: number, y: number) {
  const t = s.trail
  const n = t.length
  if (n >= 2 && Math.abs(t[n - 2] - x) < MIN_STEP && Math.abs(t[n - 1] - y) < MIN_STEP) return
  if (n >= MAX_POINTS * 2) {
    const thinned: number[] = []
    for (let i = 0; i < n - 2; i += 4) thinned.push(t[i], t[i + 1])
    thinned.push(t[n - 2], t[n - 1])
    s.trail = thinned
  }
  s.trail.push(x, y)
}

const who = (p: any) => `${p.pointerType} ${p.pointerId}`

export function onEvent(app: FrameOSApp, context: FrameOSContext) {
  const s = load()
  const p = context.payload || {}
  const event = context.event
  const x = Number.isFinite(p.x) ? Math.round(p.x) : s.x
  const y = Number.isFinite(p.y) ? Math.round(p.y) : s.y
  if (event === 'pointerMove') {
    // Only the pointer that pressed, while it is held: a mouse moving with
    // nothing pressed, or another finger, draws nothing and costs no render.
    if (!s.down || p.pointerId !== s.id) return false
    if (p.buttons === 0) {
      // Its release went somewhere else (another scene showed meanwhile).
      s.down = false
      keep()
      return true
    }
    if (x === s.x && y === s.y) return false
    s.x = x
    s.y = y
    s.moves++
    s.last = `pointerMove (${who(p)})`
    add(s, x, y)
    // Kept at the next render or at the lift, not at every move.
    return !s.paper
  }
  s.x = x
  s.y = y
  s.count++
  if (event === 'pointerDown') {
    s.down = true
    s.id = p.pointerId
    s.moves = 0
    s.trail = [x, y]
    s.last = `pointerDown (${who(p)}, button ${p.button})`
  } else if (event === 'pointerUp' || event === 'pointerCancel') {
    if (s.down && p.pointerId === s.id) {
      add(s, x, y)
      s.down = false
    }
    s.last = `${event} (${who(p)})`
  } else if (event === 'swipe') {
    s.last = `swipe ${p.direction}`
  } else if (event === 'longPress') {
    s.last = `longPress (${p.durationMs} ms)`
  } else {
    s.last = event
  }
  keep()
  // E-paper shows the press with the rest of the gesture.
  return !(s.paper && event === 'pointerDown')
}

export function get(app: FrameOSApp, context: FrameOSContext) {
  const s = load()
  // Read here: a render has the canvas that says what the panel is, and an
  // event has none to ask.
  s.paper = app.frame.paper === true
  keep()
  const scale = app.frame.scale || 1
  const width = context.imageWidth ?? app.frame.width
  const height = context.imageHeight ?? app.frame.height
  const at = (v: number) => Math.round((v / scale) * 10) / 10
  const radius = Math.max(6, Math.round(Math.min(width * scale, height * scale) / 24)) / scale
  const ink = s.down ? '#d13c3c' : '#2f6fe0'
  const pale = s.down ? '#f0a8a8' : '#a8c2f2'
  const x = at(s.x)
  const y = at(s.y)
  const r = at(3)

  const t = s.trail
  const points = t.length / 2
  const pieces: any[] = []
  for (let start = 0; start < points; start += PIECE) {
    // A piece's line runs on to the next piece's first point, so they join.
    const end = Math.min(points, start + PIECE + 1)
    let line = ''
    let dots = ''
    for (let i = start; i < end; i++) {
      const px = at(t[2 * i])
      const py = at(t[2 * i + 1])
      line += `${i === start ? 'M' : 'L'}${px} ${py}`
      if (i < start + PIECE) dots += `M${at(t[2 * i] - 3)} ${py}a${r} ${r} 0 1 0 ${2 * r} 0a${r} ${r} 0 1 0 ${-2 * r} 0`
    }
    if (end - start > 1) {
      pieces.push(<path d={line} fill="none" stroke={pale} strokeWidth={r} strokeLinecap="round" strokeLinejoin="round" />)
    }
    pieces.push(<path d={dots} fill={ink} />)
  }

  // Hairlines around the dot, long enough to show past a finger on it. Not
  // across the whole picture: a line that long moves with every move, and a
  // move would repaint all of it.
  const near = radius + at(4)
  const far = radius * 4
  const hair = 1 / scale
  const shown = s.count > 0 // nothing to point at before the first touch
  // What changes at every move (where, how many moves) is on short lines of
  // its own, apart: a move repaints those two and not the whole block.
  const lines = [s.last, `x ${s.x}, y ${s.y}`, `${s.count} events`]
  if (s.moves) lines.push(`${s.moves} moves`)
  return (
    <svg viewBox={`0 0 ${width} ${height}`} width={width} height={height}>
      <rect x="0" y="0" width={width} height={height} fill="#ffffff" />
      {shown ? [
        <line x1={x} y1={y - far} x2={x} y2={y - near} stroke="#999999" strokeWidth={hair} />,
        <line x1={x} y1={y + near} x2={x} y2={y + far} stroke="#999999" strokeWidth={hair} />,
        <line x1={x - far} y1={y} x2={x - near} y2={y} stroke="#999999" strokeWidth={hair} />,
        <line x1={x + near} y1={y} x2={x + far} y2={y} stroke="#999999" strokeWidth={hair} />,
      ] : []}
      {pieces}
      {points > 0 ? <circle cx={at(t[0])} cy={at(t[1])} r={radius + at(5)} fill="none" stroke={ink} strokeWidth={r} /> : []}
      {shown ? <circle cx={x} cy={y} r={radius} fill={ink} /> : []}
      {lines.map((text, i) => (
        <text x={at(12)} y={at(38 + i * 32)} fontSize={at(28)} fill="#000000">{text}</text>
      ))}
    </svg>
  )
}
